import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long t = nextLong();
        String[] users = new String[n];
        long[] times = new long[n];
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            users[i] = next();
            times[i] = nextLong();
            order[i] = i;
        }
        // Sorting by (user, time) puts each user's events together in time order.
        Arrays.sort(order, (x, y) -> {
            int c = users[x].compareTo(users[y]);
            return c != 0 ? c : Long.compare(times[x], times[y]);
        });
        long answer = 0;
        for (int k = 0; k < n; k++) {
            int cur = order[k];
            if (k == 0) {
                answer++;
                continue;
            }
            int prev = order[k - 1];
            if (!users[cur].equals(users[prev]) || times[cur] - times[prev] > t) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"cmp"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

type event struct {
	user string
	time int64
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	t := nextInt()
	events := make([]event, n)
	for i := range events {
		events[i].user = nextToken()
		events[i].time = nextInt()
	}
	// Sorting by (user, time) puts each user's events together in time order.
	slices.SortFunc(events, func(x, y event) int {
		if c := cmp.Compare(x.user, y.user); c != 0 {
			return c
		}
		return cmp.Compare(x.time, y.time)
	})
	answer := 0
	for i, e := range events {
		if i == 0 || e.user != events[i-1].user || e.time-events[i-1].time > t {
			answer++
		}
	}
	fmt.Println(answer)
}
